import SwiftUI

/// The admin's theme system, ported to Swift.
///
/// Values are transcribed verbatim from `packages/admin/src/theme-tokens.css`
/// (itself generated by `.audit/themes/gen-tokens.cjs`) — 4 themes × light/dark,
/// each WCAG AA verified there. Do NOT hand-tune these: fix the generator, then
/// re-transcribe, so web and mobile never drift into two different palettes.
///
/// SellRight has no locked Right Suite brand identity yet, so Vermillion is the
/// default here exactly as it is on the web.
enum ThemeName: String, CaseIterable, Identifiable {
    case vermillion, graphite, porcelain, carbon
    var id: String { rawValue }

    var label: String {
        switch self {
        case .vermillion: return "Vermillion"
        case .graphite: return "Graphite"
        case .porcelain: return "Porcelain"
        case .carbon: return "Carbon"
        }
    }
}

/// Light / Dark / System, mirroring the web switcher's three options.
enum ThemeMode: String, CaseIterable, Identifiable {
    case system, light, dark
    var id: String { rawValue }

    var label: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }

    var colorScheme: ColorScheme? {
        switch self {
        case .system: return nil
        case .light: return .light
        case .dark: return .dark
        }
    }
}

/// One theme's colors for one appearance.
struct ThemePalette {
    let bg: Color
    let surface: Color
    let surface2: Color
    let border: Color
    let borderStrong: Color
    let text: Color
    let textMuted: Color
    let textSubtle: Color
    let accent: Color
    let accentHover: Color
    let onAccent: Color
    let accentSoft: Color
    let success: Color
    let warning: Color
    let danger: Color
}

/// `rgb(203 61 20)` in the CSS → the same channel triple here. sRGB, matching
/// how the browser interprets the token.
private func c(_ r: Double, _ g: Double, _ b: Double) -> Color {
    Color(.sRGB, red: r / 255, green: g / 255, blue: b / 255, opacity: 1)
}

