    /// Order/product state → color. Semantic tokens, not raw SwiftUI colors, so
    /// states re-theme with everything else.
    static func statusColor(_ state: String, _ p: ThemePalette) -> Color {
        switch state {
        case "Paid", "Delivered", "active": return p.success
        case "PaymentPending", "Draft", "draft": return p.warning
        case "Cancelled", "Refunded", "PartiallyRefunded": return p.danger
        case "Shipped": return p.accent
        default: return p.textMuted
        }
    }
}

/// Live theme selection. Persisted to UserDefaults, same as the web switcher
/// persists to localStorage.
@MainActor
@Observable
final class ThemeStore {
    var name: ThemeName {
        didSet { UserDefaults.standard.set(name.rawValue, forKey: "themeName") }
    }
    var mode: ThemeMode {
        didSet { UserDefaults.standard.set(mode.rawValue, forKey: "themeMode") }
    }

    init() {
        let storedName = UserDefaults.standard.string(forKey: "themeName") ?? ""
        let storedMode = UserDefaults.standard.string(forKey: "themeMode") ?? ""
        name = ThemeName(rawValue: storedName) ?? .vermillion
        mode = ThemeMode(rawValue: storedMode) ?? .system
    }

    /// Resolve against the environment's scheme when mode is .system.
    func palette(for scheme: ColorScheme) -> ThemePalette {
        let dark = mode == .system ? (scheme == .dark) : (mode == .dark)
        return Theme.palette(name, dark: dark)
    }
}

// MARK: - Environment plumbing

private struct PaletteKey: EnvironmentKey {
    static let defaultValue = Theme.palette(.vermillion, dark: false)
}

extension EnvironmentValues {
    /// The active palette. Read as `@Environment(\.palette) private var palette`.
    var palette: ThemePalette {
        get { self[PaletteKey.self] }
        set { self[PaletteKey.self] = newValue }
    }
}

/// Capsule badge for order/product state. Color + text; the web pairs these with
/// a status dot for colorblind safety, and the label here carries the same job.
struct StatusBadge: View {
    @Environment(\.palette) private var palette
    let text: String

    var body: some View {
        let color = Theme.statusColor(text, palette)
        Text(text)
            .font(.caption2.weight(.semibold))
            .padding(.horizontal, 8)
            .padding(.vertical, 3)
            .background(color.opacity(0.15), in: Capsule())
            .foregroundStyle(color)
    }
}
